import React from 'react';
import {
  Page,
  PageHeader,
  PageSection,
  Title,
  Card,
  CardTitle,
  CardBody,
  Button,
  Text,
  Grid,
  GridItem,
  Label
} from '@patternfly/react-core';
import { BuilderImageIcon, CubesIcon, PlayIcon } from '@patternfly/react-icons';

const App: React.FC = () => {
  const [environments, setEnvironments] = React.useState([]);
  const [loading, setLoading] = React.useState(true);

  React.useEffect(() => {
    // Fetch environments from our API
    fetch('http://localhost:8000/api/environments')
      .then(res => res.json())
      .then(data => {
        setEnvironments(data);
        setLoading(false);
      })
      .catch(err => {
        console.error('Failed to fetch environments:', err);
        setLoading(false);
      });
  }, []);

  const Header = (
    <PageHeader
      logo={
        <div style={{ display: 'flex', alignItems: 'center' }}>
          <BuilderImageIcon style={{ marginRight: '8px' }} />
          <span>EE Containers Builder</span>
        </div>
      }
    />
  );

  return (
    <Page header={Header}>
      <PageSection variant="light">
        <Title headingLevel="h1" size="2xl">
          <CubesIcon style={{ marginRight: '12px' }} />
          Welcome to EE Containers Builder
        </Title>
        <Text component="p">
          Build and manage Ansible Execution Environments with ease
        </Text>
      </PageSection>

      <PageSection>
        <Grid hasGutter>
          <GridItem lg={6} md={12}>
            <Card>
              <CardTitle>Available Environments</CardTitle>
              <CardBody>
                {loading ? (
                  <Text>Loading environments...</Text>
                ) : (
                  <div>
                    {environments.map((env: any) => (
                      <div key={env.name} style={{ marginBottom: '16px' }}>
                        <Text component="b">{env.name}</Text>
                        <br />
                        <Text component="small">{env.description}</Text>
                        <br />
                        <Label color="blue">{env.type.toUpperCase()}</Label>
                        <Label color="purple" style={{ marginLeft: '8px' }}>
                          {env.os_version.toUpperCase()}
                        </Label>
                      </div>
                    ))}
                  </div>
                )}
              </CardBody>
            </Card>
          </GridItem>

          <GridItem lg={6} md={12}>
            <Card>
              <CardTitle>Quick Actions</CardTitle>
              <CardBody>
                <Button
                  variant="primary"
                  icon={<PlayIcon />}
                  style={{ marginBottom: '16px' }}
                >
                  Start New Build
                </Button>
                <br />
                <Text component="small">
                  API Status: Connected ✅
                  <br />
                  Backend URL: http://localhost:8000
                </Text>
              </CardBody>
            </Card>
          </GridItem>
        </Grid>
      </PageSection>
    </Page>
  );
};

export default App;
